public static void main(String[] args)
{
    FastReader sc = new FastReader();
    PrintWriter out = new PrintWriter(System.out);
    int n = sc.nextInt();
    int[] arr = new int[2 * n];
    for (int i = 0; i < 2 * n; ++i) arr[i] = sc.nextInt();
    int c = 0;
    for (int i = 0; i < 2 * n - 2; ++i) {
        if (arr[i] == arr[i + 2]) ++c;
    }
    out.println(c);
    out.flush();
}
